  },
  get: {
    python: (c) => `${c.recv}[${c.args[0] ?? 0}]`,
    typescript: (c) => `${c.recv}[${c.args[0] ?? 0}]`,
    javascript: (c) => `${c.recv}[${c.args[0] ?? 0}]`,
    rust: (c) => `${c.recv}[${c.args[0] ?? 0}]`,
    go: (c) => `${c.recv}[${c.args[0] ?? 0}]`,
    cpp: (c) => `${c.recv}[${c.args[0] ?? 0}]`,
  },
  contains: {
    python: (c) => `(${c.args[0]} in ${c.recv})`,
