      m.delete(a[0]);
      return someV(v);
    },
  },
  clear: { mutating: true, fn: (r) => { (r as Map<unknown, unknown>).clear(); return undefined; } },
  keys: { fn: (r) => [...(r as Map<unknown, unknown>).keys()] },
